"""Configuration loading.

Two files, both under ``config/`` at the repository root:

* ``ankelbot_params.json`` is generated by MATLAB (``matlab/export_reference.m``).
  It holds the physical model, the controller gains designed in MATLAB and all
  decision thresholds. It is never edited by hand.
* ``onboard.json`` is the hardware wiring of one particular vessel: camera
  source, model weights, MAVLink port, servo channels, storage path.
"""
from __future__ import annotations

import json
from pathlib import Path
from types import SimpleNamespace
from typing import Any

REPO_ROOT = Path(__file__).resolve().parents[2]
PARAMS_FILE = REPO_ROOT / "config" / "ankelbot_params.json"
ONBOARD_FILE = REPO_ROOT / "config" / "onboard.json"


def _ns(obj: Any) -> Any:
    if isinstance(obj, dict):
        return SimpleNamespace(**{k: _ns(v) for k, v in obj.items()})
    return obj


def load_params(path: Path | str = PARAMS_FILE) -> SimpleNamespace:
    """Model parameters and gains exported from MATLAB, with attribute access."""
    with open(path, "r", encoding="utf-8") as f:
        return _ns(json.load(f))


def load_onboard(path: Path | str = ONBOARD_FILE) -> SimpleNamespace:
    """Per-vessel hardware configuration."""
    with open(path, "r", encoding="utf-8") as f:
        return _ns(json.load(f))
